// Oracle transcribed from be8c47c, with the index_selector exception derived
// from F0-0002 §§4.1.1, 4.1.2.3 and 4.1.2.4/N(d). Each expected value is the
// complete CLI JSON, with only the temporary source filename replaced by case.n.
use std::{
    fs,
    process::Command,
    sync::atomic::{AtomicUsize, Ordering},
};

static NEXT: AtomicUsize = AtomicUsize::new(0);

fn run_case(source: &str, mode: &str) -> (i32, String, String) {
    let path = std::env::temp_dir().join(format!(
        "i07c-s4-{}-{}.n",
        std::process::id(),
        NEXT.fetch_add(1, Ordering::Relaxed)
    ));
    fs::write(&path, source.as_bytes()).unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_nexo"))
        .args([
            mode,
            "--profile",
            "f0-0005-b-v1",
            "--format",
            "json",
            path.to_str().unwrap(),
        ])
        .output()
        .unwrap();
    fs::remove_file(&path).unwrap();
    let file_json = path.to_str().unwrap().replace('\\', "\\\\");
    let stdout = String::from_utf8(output.stdout)
        .unwrap()
        .replace(&file_json, "case.n");
    (
        output.status.code().unwrap(),
        stdout,
        String::from_utf8(output.stderr).unwrap(),
    )
}

